  4455  static stbi_uc first_row_filter[5] =
  4456  {
  4457     STBI__F_none,
  4458     STBI__F_sub,
  4459     STBI__F_none,
  4460     STBI__F_avg_first,
  4461     STBI__F_paeth_first
  4462  };
  4463
  4464  static int stbi__paeth(int a, int b, int c)
  4465  {
  4466     int p = a + b - c;
  4467     int pa = abs(p-a);
  4468     int pb = abs(p-b);
  4469     int pc = abs(p-c);
  4470     if (pa <= pb && pa <= pc) return a;
  4471     if (pb <= pc) return b;
  4472     return c;
  4473  }
