  4629                 *cur++ = scale * ((*in >> 2) & 0x03);
  4630                 *cur++ = scale * ((*in     ) & 0x03);
  4631              }
  4632              if (k > 0) *cur++ = scale * ((*in >> 6)       );
  4633              if (k > 1) *cur++ = scale * ((*in >> 4) & 0x03);
  4634              if (k > 2) *cur++ = scale * ((*in >> 2) & 0x03);
